function writeConfig(tmpDir: string, defaultRunMode = 'research-rag'): string {
  const config = JSON.parse(readFileSync(new URL('../pipeline-config.json', import.meta.url), 'utf8')) as Record<string, any>;
  config.global.dataDir = join(tmpDir, 'data');
  config.global.dossierDataDir = join(tmpDir, 'data');
  config.global.outputDir = join(tmpDir, 'output');
  config.global.codexAccountRotation = [];
  config.global.logLevel = 'error';
  config.global.defaultRunMode = defaultRunMode;
  // ANA-1 escalated scenarios_have_operational_trigger to a fatal analyze lint
  // when requireOperationalTrigger is true (the prod default). These are routing
  // tests using a stub analyze book with narrative-only indicators, so opt the
  // routing fixtures out of the operational-trigger requirement; trigger quality
  // is covered by the dedicated analyze/scenario-gate suites.
  config.thresholds = config.thresholds ?? {};
  config.thresholds.analyze = { ...(config.thresholds.analyze ?? {}), requireOperationalTrigger: false };
  for (const step of Object.values(config.steps) as Array<Record<string, any>>) {
    step.continuation.maxRounds = 1;
  }
  const path = join(tmpDir, 'pipeline-config.json');
  writeFileSync(path, JSON.stringify(config));
  return path;
}

